16	        String city = owner.getCity() == null ? "" : owner.getCity();
17	        String city3 = city.length() >= 3 ? city.substring(0, 3) : city;
18	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
19	        String last3 = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
20	        int sequence = (int) ownerRepository.findAll().stream()
21	            .filter(o -> o.getCity() != null && o.getCity().equalsIgnoreCase(city))
22	            .count() + 1;
23	        owner.setCustomerCode(String.format("%s-%s-%04d", city3.toUpperCase(), last3.toUpperCase(), sequence));
24	    }
25	}
